 * workspace retired ends that retirement. Only the slug column and
 * `updatedAt` are written.
 */
export async function replaceOrgSlug(
  orgId: OrgId,
  from: string,
  to: string,
): Promise<Organization> {
  const now = toIsoTimestamp(new Date());
  const db = getDb();

  db.delete(organizationSlugHolds)
    .where(
      and(
        eq(organizationSlugHolds.orgId, orgId),
        eq(organizationSlugHolds.slug, to),
      ),
    )
    .run();

  db.insert(organizationSlugHolds)
    .values({
