/**
 * Changes the workspace URL to the exact slug the caller typed. A slug that
 * fails the shared rules, or that another workspace holds (current or still
 * inside its retirement window), is refused with the invalid-slug error.
 * Renaming to the current slug changes nothing and publishes nothing.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const current = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (current.slug === input.slug) return current;

  assertValidSlug(input.slug);

  const available = await orgRepo.isOrgSlugAvailable(input.orgId, input.slug);
  if (!available) {
    throw new InvalidSlugError(input.slug, "is not available");
  }

  const updated = await orgRepo.replaceOrgSlug(
    input.orgId,
    current.slug,
    input.slug,
  );

  await emit("organization.slug_changed", {
    ...envelope(updated.id, actor.userId),
    from: current.slug,
    to: updated.slug,
  });

  await record(updated.id, "organization.slug_changed", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `Slug ${current.slug} → ${updated.slug}`,
    metadata: { from: current.slug, to: updated.slug },
  });

  return updated;
}

